"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["48825"],{24063(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.remanejamento_par_nao_selecionado","status":422,"titulo":"O par do remanejamento CRUZADO n\xe3o est\xe1 selecionado nesta oferta"},"descricao":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.remanejamento_par_nao_selecionado","requisitos":[],"oQueAconteceu":["Uma modalidade com `regraRemanejamento: CRUZADO` declara um\\n`remanejamentoPar` que existe no cadastro de modalidades, mas **n\xe3o est\xe1\\nentre as modalidades selecionadas nesta mesma oferta**. A valida\xe7\xe3o de\\n[`modalidade_selecionada.remanejamento_cruzado_incompleto`](/erros/uniplus.selecao.modalidade_selecionada.remanejamento_cruzado_incompleto)\\ns\xf3 prova que o par foi preenchido \u2014 esta confer\xeancia, separada, prova que ele\\naponta para algo que de fato existe **nesta** distribui\xe7\xe3o. O remanejamento cruzado \xe9 rec\xedproco entre duas modalidades da\\nmesma oferta; n\xe3o pode cruzar com uma que a oferta nem tem.","Esta confer\xeancia roda depois que todas as modalidades da distribui\xe7\xe3o j\xe1 foram\\ncriadas individualmente, sobre o conjunto delas. Verifica, para cada\\nmodalidade, a origem e o destino antes do par \u2014 ver\\n[`composicao_origem_nao_selecionada`](/erros/uniplus.selecao.configuracao_distribuicao_vagas.composicao_origem_nao_selecionada)\\npara o mecanismo completo de acumula\xe7\xe3o (com `modalidade_duplicada`, no\\nmesmo array `errors[]`) e a ordem de confer\xeancia entre modalidades e entre\\ncampos de uma mesma modalidade."],"comoResolver":["Inclua a modalidade par em `modalidadeIds`, na mesma distribui\xe7\xe3o, ou\\ncorrija, no cadastro de modalidades de Configura\xe7\xe3o, o c\xf3digo do par\\ndeclarado para apontar a uma modalidade que de fato est\xe1 sendo selecionada\\nnesta oferta."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao distribuicao vagas"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);